class Solution:
    def solveSudoku(self, board: List[List[str]]) -> None:
        def is_valid(r, c, char):
            for i in range(9):
                if board[i][c] == char or board[r][i] == char or board[3*(r//3)+i//3][3*(c//3)+i%3] == char: return False
            return True
        def solve():
            for r in range(9):
                for c in range(9):
                    if board[r][c] == '.':
                        for char in '123456789':
                            if is_valid(r, c, char):
                                board[r][c] = char
                                if solve(): return True
                                board[r][c] = '.'
                        return False
            return True
        solve()

