import sys
import json

def solveSudoku(board):
    def isValid(r, c, val):
        for i in range(9):
            if board[r][i] == val or board[i][c] == val: return False
            if board[(r//3)*3 + i//3][(c//3)*3 + i%3] == val: return False
        return True

    def solve():
        for r in range(9):
            for c in range(9):
                if board[r][c] == '.':
                    for val in "123456789":
                        if isValid(r, c, val):
                            board[r][c] = val
                            if solve(): return True
                            board[r][c] = '.'
                    return False
        return True
    solve()

