using namespace std;

bool isValid(vector<vector<char>>& board, int r, int c, char val) {
    for (int i = 0; i < 9; i++) {
        if (board[r][i] == val || board[i][c] == val) return false;
        if (board[(r/3)*3 + i/3][(c/3)*3 + i%3] == val) return false;
    }
    return true;
}

bool solve(vector<vector<char>>& board) {
    for (int r = 0; r < 9; r++) {
        for (int c = 0; c < 9; c++) {
            if (board[r][c] == '.') {
                for (char val = '1'; val <= '9'; val++) {
                    if (isValid(board, r, c, val)) {
                        board[r][c] = val;
                        if (solve(board)) return true;
                        board[r][c] = '.';
                    }
                }
                return false;
            }
        }
    }
    return true;
}

int main() {
    char c;
    vector<vector<char>> board(9, vector<char>(9));
    int r = 0, col = 0;
    while (cin >> c) {
        if (c == '"') {
            cin >> c;
            board[r][col] = c;
            cin >> c; // closing quote
            col++;
            if (col == 9) { col = 0; r++; }
            if (r == 9) break;
        }
    }
    solve(board);
    cout << "[";
    for (int i = 0; i < 9; i++) {
        cout << "[";
        for (int j = 0; j < 9; j++) {
            cout << "\"" << board[i][j] << "\"" << (j == 8 ? "" : ",");
        }
        cout << "]" << (i == 8 ? "" : ",");
    }
    cout << "]" << endl;
    return 0;
}

