import java.util.*;
import java.io.*;

public class Main {
    public static void solveSudoku(char[][] board) {
        solve(board);
    }
    private static boolean solve(char[][] board) {
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                if (board[r][c] == '.') {
                    for (char val = '1'; val <= '9'; val++) {
                        if (isValid(board, r, c, val)) {
                            board[r][c] = val;
                            if (solve(board)) return true;
                            board[r][c] = '.';
                        }
                    }
                    return false;
                }
            }
        }
        return true;
    }
    private static boolean isValid(char[][] board, int r, int c, char val) {
        for (int i = 0; i < 9; i++) {
            if (board[r][i] == val || board[i][c] == val) return false;
            if (board[(r / 3) * 3 + i / 3][(c / 3) * 3 + i % 3] == val) return false;
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) sb.append(line);
        String content = sb.toString().replace("[", "").replace("]", "").replace("\"", "").replace(",", "").replace(" ", "").trim();
        char[][] board = new char[9][9];
        for (int i = 0; i < 81; i++) board[i / 9][i % 9] = content.charAt(i);
        solveSudoku(board);
        System.out.print("[");
        for (int i = 0; i < 9; i++) {
            System.out.print("[");
            for (int j = 0; j < 9; j++) {
                System.out.print("\"" + board[i][j] + "\"" + (j == 8 ? "" : ","));
            }
            System.out.print("]" + (i == 8 ? "" : ","));
        }
        System.out.println("]");
    }
}

